  "recipeIngredient": [
    "150 grams (1¼ cups) paneer ( (Indian cottage cheese))",
    "3½ to 4 cups (100 to 120 grams) palak ((spinach) )",
    "2 tablespoons oil ((or half oil &amp; half butter))",
    "2 green chilies ((deseeded) (less spicy kind))",
    "¾ cup ( 90 grams, 1 small) onions ((fine chopped))",
    "½ cup (1 small) tomatoes ((deseeded &amp; chopped or pureed))",
    "¾ teaspoon ginger garlic paste ((read notes for substitute))",
    "½ teaspoon salt ((use as per your taste))",
    "8 to 10 cashewnuts ((read notes for substitutes))",
    "½ to ¾ teaspoon garam masala ((adjust to taste))",
    "½ teaspoon kasuri methi ((dried fenugreek leaves) (skip if you don&#039;t have))",
    "¼ cup water (to blend spinach)",
    "¾ cup water (to cook the gravy)",
    "3 tablespoons cream ((optional))",
    "⅛ teaspoon cumin seeds ((jeera) (optional))",
    "2 green cardamoms ((elaichi) (optional))",
    "1 inch cinnamon ((dalchini) (optional))",
    "2 cloves ((laung) (optional))"
  ],
  "recipeInstructions": [
    {
      "@type": "HowToSection",
      "name": "Preparation",
      "itemListElement": [
        {
          "@type": "HowToStep",
          "text": "Pluck only the young &amp; tender spinach leaves and discard the stems as they may leave a bitter taste. If using baby spinach you can use the stems as well.",
          "name": "Pluck only the young &amp; tender spinach leaves and discard the stems as they may leave a bitter taste. If using baby spinach you can use the stems as well.",
          "url": "https://www.indianhealthyrecipes.com/palak-paneer-recipe-easy-paneer-recipes-step-by-step-pics/#wprm-recipe-38742-step-0-0"
        },
        {
          "@type": "HowToStep",
          "text": "Add them to a large pot of water. Rinse them well few times &amp; drain to a colander.",
          "name": "Add them to a large pot of water. Rinse them well few times &amp; drain to a colander.",
          "url": "https://www.indianhealthyrecipes.com/palak-paneer-recipe-easy-paneer-recipes-step-by-step-pics/#wprm-recipe-38742-step-0-1"
        },
        {
          "@type": "HowToStep",
          "text": "Allow the water to drain completely otherwise it will let out lot of moisture while cooking.",
          "name": "Allow the water to drain completely otherwise it will let out lot of moisture while cooking.",
          "url": "https://www.indianhealthyrecipes.com/palak-paneer-recipe-easy-paneer-recipes-step-by-step-pics/#wprm-recipe-38742-step-0-2"
        },
        {
          "@type": "HowToStep",
          "text": "Heat half tablespoon oil in a pan. Saute green chilies, cashews and spinach for 3 to 4 mins until the leaves wilt off thoroughly &amp; raw smell of spinach has gone away. [OR another option is to blanch the palak in 4 cups of hot water with ¼ tsp salt for 2 mins. Then immerse in ice cold water. Drain completely.]",
          "name": "Heat half tablespoon oil in a pan. Saute green chilies, cashews and spinach for 3 to 4 mins until the leaves wilt off thoroughly &amp; raw smell of spinach has gone away. [OR another option is to blanch the palak in 4 cups of hot water with ¼ tsp salt for 2 mins. Then immerse in ice cold water. Drain completely.]",
          "url": "https://www.indianhealthyrecipes.com/palak-paneer-recipe-easy-paneer-recipes-step-by-step-pics/#wprm-recipe-38742-step-0-3"
        },
        {
          "@type": "HowToStep",
          "text": "Cool this completely. Blend this along with water to a smooth puree. The puree should be smooth and thick. You may add 1 to 2 tbsps more water to help in blending.",
          "name": "Cool this completely. Blend this along with water to a smooth puree. The puree should be smooth and thick. You may add 1 to 2 tbsps more water to help in blending.",
          "url": "https://www.indianhealthyrecipes.com/palak-paneer-recipe-easy-paneer-recipes-step-by-step-pics/#wprm-recipe-38742-step-0-4"
        }
      ]
    },
    {
      "@type": "HowToSection",
      "name": "How to make Palak Paneer",
      "itemListElement": [
        {
          "@type": "HowToStep",
          "text": "Heat 1 tablespoon butter and half tablespoon oil to the same pan, Once they melt, add cinnamon, cardamoms, cloves &amp; cumin seeds.",
          "name": "Heat 1 tablespoon butter and half tablespoon oil to the same pan, Once they melt, add cinnamon, cardamoms, cloves &amp; cumin seeds.",
          "url": "https://www.indianhealthyrecipes.com/palak-paneer-recipe-easy-paneer-recipes-step-by-step-pics/#wprm-recipe-38742-step-1-0"
        },
        {
          "@type": "HowToStep",
          "text": "When the spices begin to sizzle, add onions and fry till they turn transparent to golden.",
          "name": "When the spices begin to sizzle, add onions and fry till they turn transparent to golden.",
          "url": "https://www.indianhealthyrecipes.com/palak-paneer-recipe-easy-paneer-recipes-step-by-step-pics/#wprm-recipe-38742-step-1-1"
        },
        {
          "@type": "HowToStep",
          "text": "Next saute ginger garlic paste for 1 to 2 minutes or until you begin to smell it nice.",
          "name": "Next saute ginger garlic paste for 1 to 2 minutes or until you begin to smell it nice.",
          "url": "https://www.indianhealthyrecipes.com/palak-paneer-recipe-easy-paneer-recipes-step-by-step-pics/#wprm-recipe-38742-step-1-2"
        },
        {
          "@type": "HowToStep",
          "text": "Then add tomatoes with salt. Saute until they break down and turn mushy.",
          "name": "Then add tomatoes with salt. Saute until they break down and turn mushy.",
          "url": "https://www.indianhealthyrecipes.com/palak-paneer-recipe-easy-paneer-recipes-step-by-step-pics/#wprm-recipe-38742-step-1-3"
        },
        {
          "@type": "HowToStep",
          "text": "Add garam masala &amp; saute until the masala smells good. This may take 2 mins. (for a smoother curry refer notes)",
          "name": "Add garam masala &amp; saute until the masala smells good. This may take 2 mins. (for a smoother curry refer notes)",
          "url": "https://www.indianhealthyrecipes.com/palak-paneer-recipe-easy-paneer-recipes-step-by-step-pics/#wprm-recipe-38742-step-1-4"
        },
        {
          "@type": "HowToStep",
          "text": "Pour water and cook covered until onions are completely soft. There should be some water left in the pan. (for consistency check video)",
          "name": "Pour water and cook covered until onions are completely soft. There should be some water left in the pan. (for consistency check video)",
          "url": "https://www.indianhealthyrecipes.com/palak-paneer-recipe-easy-paneer-recipes-step-by-step-pics/#wprm-recipe-38742-step-1-5"
        },
        {
          "@type": "HowToStep",
          "text": "Lower the flame, add kasuri methi and pureed spinach. Mix well and cook until it begins to bubble for about 2 to 3 mins. If the curry is too thick you may add a few tbsps of hot water.",
          "name": "Lower the flame, add kasuri methi and pureed spinach. Mix well and cook until it begins to bubble for about 2 to 3 mins. If the curry is too thick you may add a few tbsps of hot water.",
          "url": "https://www.indianhealthyrecipes.com/palak-paneer-recipe-easy-paneer-recipes-step-by-step-pics/#wprm-recipe-38742-step-1-6"
        },
        {
          "@type": "HowToStep",
          "text": "Avoid overcooking. Add paneer &amp; mix well. Turn off and remove to a serving bowl. Optionally garnish with cream.",
          "name": "Avoid overcooking. Add paneer &amp; mix well. Turn off and remove to a serving bowl. Optionally garnish with cream.",
          "url": "https://www.indianhealthyrecipes.com/palak-paneer-recipe-easy-paneer-recipes-step-by-step-pics/#wprm-recipe-38742-step-1-7"
        },
        {
          "@type": "HowToStep",
          "text": "Serve palak paneer with naan, roti, Basmati rice or Jeera rice.",
          "name": "Serve palak paneer with naan, roti, Basmati rice or Jeera rice.",
          "url": "https://www.indianhealthyrecipes.com/palak-paneer-recipe-easy-paneer-recipes-step-by-step-pics/#wprm-recipe-38742-step-1-8"
        }
      ]
    }
  ],
